// n8n's $getWorkflowStaticData('global') is scoped to the CURRENT workflow.
// So this workflow owns its own dailyCounters - it cannot read counters
// written by other workflows. Every Discord MESSAGE_CREATE that the gateway
// bridge fans out to '/webhook/discord/message-create/stats' lands here
// and bumps the daily message counter.
const sd = $getWorkflowStaticData('global');
sd.dailyCounters = sd.dailyCounters || { messages: 0, joins: 0, leaves: 0 };
sd.dailyCounters.messages = (sd.dailyCounters.messages || 0) + 1;
return [{ json: { ok: true } }];

// Same scoping note as 'Increment messages': dailyCounters live in this
// workflow's static data. The gateway bridge forwards GUILD_MEMBER_ADD to
// '/webhook/discord/stats/member-join' specifically for this counter so
// it does not collide with the welcome workflow's own '/discord/member-join'.
const sd = $getWorkflowStaticData('global');
sd.dailyCounters = sd.dailyCounters || { messages: 0, joins: 0, leaves: 0 };
sd.dailyCounters.joins = (sd.dailyCounters.joins || 0) + 1;
return [{ json: { ok: true } }];

const body = $input.first().json?.body;
if (body && body.commandName !== 'stats') {
  return [{ json: { skip: true } }];
}
return [{
  json: {
    skip: false,
    isManual: !!body,
    interactionToken: body?.interactionToken,
    applicationId: body?.applicationId,
    channelId: body?.channelId,
  }
}];

// Workflow 09's $getWorkflowStaticData('global') is scoped to this workflow,
// so XP data written by workflow 07 (leveling) is NOT visible here. We do
// not try to compute a top-XP leaderboard - that lives in workflow 07's
// /leaderboard command, which has direct access to the XP store.
const guild = $('Discord: fetch guild stats').first().json;
// Guard with Array.isArray in case Discord returns an error object instead of
// the channels array (missing bot permissions, rate limit, etc).
const rawChannels = $('Discord: fetch channels').first().json;
const channels = Array.isArray(rawChannels) ? rawChannels : [];
const staticData = $getWorkflowStaticData('global');
const counters = staticData.dailyCounters || { messages: 0, joins: 0, leaves: 0 };

const textChannels = channels.filter(c => c.type === 0).length;
const voiceChannels = channels.filter(c => c.type === 2).length;
const categories = channels.filter(c => c.type === 4).length;

const totalMembers = guild.approximate_member_count || 0;
const onlineMembers = guild.approximate_presence_count || 0;

// Pull interaction context from Gate trigger if /stats was invoked manually.
// `$('Gate trigger').first()` throws when the cron path was taken, so guard it.
let gate = null;
try { gate = $('Gate trigger').first().json; } catch { gate = null; }

const isManual = !!(gate && gate.isManual);

const report = {
  guildName: guild.name,
  totalMembers,
  onlineMembers,
  textChannels,
  voiceChannels,
  categories,
  messagesToday: counters.messages,
  joinsToday: counters.joins,
  leavesToday: counters.leaves,
  isManual,
  interactionToken: gate?.interactionToken || null,
  applicationId: gate?.applicationId || null,
};

// Only the midnight cron run rolls the counters over. A manual /stats
// invocation must NOT wipe them - otherwise the cron report later that day
// would only see post-/stats activity.
if (!isManual) {
  staticData.dailyCounters = { messages: 0, joins: 0, leaves: 0 };
}

return [{ json: report }];

const r = $input.first().json;
const embed = {
  title: `📊 إحصائيات ${r.guildName} اليومية`,
  color: 5814783,
  fields: [
    { name: '👥 الأعضاء', value: `${r.totalMembers} (${r.onlineMembers} متصلين)`, inline: true },
    { name: '📝 رسائل اليوم', value: String(r.messagesToday), inline: true },
    { name: '➕ انضموا اليوم', value: String(r.joinsToday), inline: true },
    { name: '➖ غادروا اليوم', value: String(r.leavesToday), inline: true },
    { name: '💬 قنوات نصية', value: String(r.textChannels), inline: true },
    { name: '🎙️ قنوات صوتية', value: String(r.voiceChannels), inline: true },
    { name: '🏆 لوحة الصدارة', value: 'استخدم /leaderboard لعرض أعلى الأعضاء بالخبرة', inline: false },
  ],
  timestamp: new Date().toISOString(),
  footer: { text: 'تقرير يومي تلقائي' }
};
return [{ json: { embed, isManual: r.isManual, interactionToken: r.interactionToken, applicationId: r.applicationId } }];
